MODULE GATH_GRID_32_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to GATH_GRID_32
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPGPG_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKTO_SHAPE(1)
  INTEGER(KIND=C_INT) :: IGP_SHAPE(3)
END TYPE ARGS_INFO

END MODULE GATH_GRID_32_ARGS_INFO_MOD

SUBROUTINE GATH_GRID_32(PGPG, KPROMA, KFGATHG, KTO, KRESOL, PGP)

USE PARKIND1,                    ONLY: JPRM, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE GATH_GRID_32_ARGS_INFO_MOD,  ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
! PGPG and PGP are always single precision (32-bit), so a single binding covers both build precisions.
SUBROUTINE GATH_GRID_32_CPP_BINDING(ARGS, KPROMA, KFGATHG, KRESOL, PGPG, KTO, PGP) &
  &  BIND(C, NAME="gath_grid_32")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE GATH_GRID_32_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KPROMA
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFGATHG
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(OUT) :: PGPG(*)
  INTEGER(KIND=C_INT),           INTENT(IN)  :: KTO(*)
  REAL(KIND=C_FLOAT),            INTENT(IN)  :: PGP(*)
END SUBROUTINE GATH_GRID_32_CPP_BINDING
END INTERFACE

REAL(KIND=JPRM),    OPTIONAL, INTENT(OUT) :: PGPG(:,:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPROMA
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFGATHG
INTEGER(KIND=JPIM),           INTENT(IN)  :: KTO(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
REAL(KIND=JPRM),              INTENT(IN)  :: PGP(:,:,:)

TYPE(ARGS_INFO) :: ARGS

TYPE(C_PTR) :: KPROMA_PTR, KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IPROMA, IRESOL

IF (PRESENT(PGPG)) THEN
  ARGS%IPGPG_SHAPE = SHAPE(PGPG, KIND=C_INT)
ELSE
  ARGS%IPGPG_SHAPE = 0_C_INT
ENDIF
ARGS%IKTO_SHAPE = SHAPE(KTO, KIND=C_INT)
ARGS%IGP_SHAPE = SHAPE(PGP, KIND=C_INT)

IF (PRESENT(KPROMA)) THEN
  IPROMA = KPROMA
  KPROMA_PTR = C_LOC(IPROMA)
ELSE
  KPROMA_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

CALL GATH_GRID_32_CPP_BINDING(ARGS, KPROMA_PTR, KFGATHG, KRESOL_PTR, PGPG=PGPG, KTO=KTO, PGP=PGP)

END SUBROUTINE GATH_GRID_32
